"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["33952"],{67632(e){e.exports=JSON.parse('{"id":"F139","slug":"cash-flow-quality","name":"Cash Flow Quality Ratios","subject":"Financial Statement Analysis","section":"Quality & Red Flags","topic":"Cash flow quality: operating cash flow vs. earnings","level":"Intermediate","aliases":["operating cash flow to net income","cash flow adequacy","CFO to EBITDA"],"formula":{"latex":"\\\\frac{CFO}{NI},\\\\quad \\\\frac{CFO}{EBITDA},\\\\quad \\\\text{Adequacy}=\\\\frac{CFO}{\\\\text{CapEx}+\\\\text{Dividends}+\\\\text{Debt repaid}}","also":[],"text":"CFO / Net income; CFO / EBITDA; Cash flow adequacy = CFO / (Capex + Dividends + Debt repayments)"},"symbols":[{"symbol":"CFO","meaning":"Cash flow from operations","unit":"money"},{"symbol":"NI","meaning":"Net income","unit":"money"},{"symbol":"EBITDA","meaning":"Earnings before interest, tax, depreciation and amortization","unit":"money"}],"when_to_use":"Use it to judge whether operations pay for themselves. CFO well above net income is usually a sign of good quality (but check for working capital being squeezed). Adequacy above 1 means operating cash covers investment, dividends and debt repayment without outside funding.","worked_example":{"problem":"A company has operating cash flow of 140, net income of 90 and EBITDA of 260. It spends 80 on capital, 30 on dividends and 20 on debt repayment.","inputs":{"cfo":140,"ni":90,"ebitda":260,"capex":80,"div":30,"rep":20},"steps":[{"label":"CFO / net income","working":"140 / 90","value":"1.56"},{"label":"CFO / EBITDA","working":"140 / 260","value":"0.54"},{"label":"Adequacy = CFO / (capex + dividends + debt repaid)","working":"140 / (80+30+20)","value":"1.08"}],"answer":"CFO is 1.56 of net income and 0.54 of EBITDA. Cash flow adequacy is 1.08, so operations cover all the main uses of cash with a small surplus."},"calculator":{"available":true,"inputs":[{"id":"cfo","label":"Cash flow from operations","unit":"money","type":"number","default":140,"hint":""},{"id":"ni","label":"Net income","unit":"money","type":"number","default":90,"hint":""},{"id":"ebitda","label":"EBITDA","unit":"money","type":"number","default":260,"hint":""},{"id":"capex","label":"Capital expenditure","unit":"money","type":"number","default":80,"hint":""},{"id":"div","label":"Dividends paid","unit":"money","type":"number","default":30,"hint":""},{"id":"rep","label":"Debt repaid","unit":"money","type":"number","default":20,"hint":""}],"checks":[{"expr":"ni>0 and ebitda>0 and capex+div+rep>0","message":"Net income, EBITDA and the uses of cash must be above zero."}],"steps":[{"id":"cn","label":"CFO / net income","expr":"cfo/ni","format":"num2"},{"id":"ce","label":"CFO / EBITDA","expr":"cfo/ebitda","format":"num2"},{"id":"adq","label":"Adequacy = CFO / (capex + dividends + debt repaid)","expr":"cfo/(capex+div+rep)","format":"num2"}],"results":["cn","ce","adq"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"cn":1.5555555555555556,"ce":0.5384615384615384,"adq":1.0769230769230769}},"finder":{"finds":"Whether profit turns into cash and cash covers needs","needs":"CFO, net income, EBITDA, capex, dividends, debt repayments"},"related":[{"slug":"accrual-ratio","name":"Accrual Ratio (Earnings Quality)"},{"slug":"free-cash-flow-conversion","name":"Free Cash Flow vs. Net Income"},{"slug":"ebitda-and-its-limits","name":"EBITDA and Its Limits"}],"related_ids":["F137","F138","F140"],"group":"Companies and valuation","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mfrac><mrow><mi>C</mi><mi>F</mi><mi>O</mi></mrow><mrow><mi>N</mi><mi>I</mi></mrow></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mfrac><mrow><mi>C</mi><mi>F</mi><mi>O</mi></mrow><mrow><mi>E</mi><mi>B</mi><mi>I</mi><mi>T</mi><mi>D</mi><mi>A</mi></mrow></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Adequacy</mtext><mo>=</mo><mfrac><mrow><mi>C</mi><mi>F</mi><mi>O</mi></mrow><mrow><mtext>CapEx</mtext><mo>+</mo><mtext>Dividends</mtext><mo>+</mo><mtext>Debt\xa0repaid</mtext></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">\\\\frac{CFO}{NI},\\\\quad \\\\frac{CFO}{EBITDA},\\\\quad \\\\text{Adequacy}=\\\\frac{CFO}{\\\\text{CapEx}+\\\\text{Dividends}+\\\\text{Debt repaid}}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"cash-conversion-from-statements","name":"Cash Conversion Cycle from the Financial Statements"},"next":{"slug":"cash-ratio-defensive-interval","name":"Cash Ratio and Defensive Interval"},"lesson":null,"total":522}')}}]);